mapper.sql:
FROM sys_user u LEFT JOIN sys_dept d ON u.dept_id = d.id LEFT JOIN sys_post p ON u.post_id = p.id WHERE 1 = 1
AND (u.real_name LIKE CONCAT('%', #{kw}, '%') OR u.username LIKE CONCAT('%', #{kw}, '%') OR u.phone LIKE CONCAT('%', #{kw}, '%'))
AND (u.dept_id = #{deptId} OR d.parent_id = #{deptId}) AND u.status = #{status}
